'use strict';
/* ============ expedition/mega.js — Mega Evolution (MicaSurvivor DLC D14, not upstream) ============
 * Lazy-loaded with the rest of js/expedition/ (G.Expedition.load()); a base page never runs it. Owner decision #10 ("include
 * Mega Evolution in 1.0"), the study's 5.5 ("Mega Evolutions as a late-run power spike") and the owner's roster update (every
 * species that can Mega Evolve is in the League, "Mega at the capable stage"). The data is js/expedition/mega-data.js
 * (GENERATED by tools/micasurvivor/gen_megas.mjs from PokéAPI's -mega varieties: 93 Megas of 87 species).
 *
 *   when      a League run whose form can Mega Evolve (Charizard, Gardevoir, Lucario, Raichu...), from Lv 40 (K.LV): that
 *             level-up's cards ARE the choice, one gold card per Mega (Charizard: X or Y) and "Not yet" (offered again
 *             K.AGAIN levels later). Once a run; it lasts the rest of the run (js/expedition/league.js megaCards / megaEvolve)
 *   what      the Mega's REAL base stats (HP the same, +100 elsewhere) and types (Charizard X: Fire / Dragon, so its verbs
 *             change too: no more glide), and the Ultimate one tier up (js/expedition/ultimates.js tierOfRow). The passive,
 *             the kit and Maturity stay the member's
 *   the look  EXISTING ART ONLY (owner): the overworld battle system's own Mega sprite (overworld/data/pokemon/<spr>: the 48 of
 *             Gen 6-7), drawn at the member's size, mirrored for the right-facing rows (it faces left, like B1c's battle
 *             fronts), with the walking hop and the hurt flash. A Mega without one there (the Legends Z-A ones, the Z forms) is
 *             COMPOSED from the member's own animated sheet. Every Mega carries the same two code-drawn marks: a Mega aura at
 *             its feet and the keystone's three-colour sign over its head. Nothing is a placeholder.
 *   sync      the League row's 6th field is the Mega's id (PokéAPI's form id, 0 none): a viewer / co-op puppet takes the
 *             look from it (G.ExpLeague.applyRow). Older readers ignore the field, so the `x` block stays v10.
 */
G.ExpEN = Object.assign(G.ExpEN || {}, {
  'Mega-{x}': 'Mega {x}', 'MEGAEVOLUCIÓN': 'MEGA EVOLUTION', '¡{x} megaevoluciona a {x}!': '{x} Mega Evolved into {x}!',
  'Todavía no': 'Not yet', 'Sigue como {x}; se ofrece otra vez dentro de {x} niveles': 'Stay as {x}; offered again in {x} levels',
  '¿Megaevoluciona {x}?': 'Mega Evolve {x}?', '{x} · Vida {x} → {x} · definitivo +1': '{x} · HP {x} → {x} · Ultimate +1',
  'desde Nv. {x}': 'from Lv {x}', 'Liga: {x}': 'League: {x}'
});
G.I18n.add(G.ExpEN);

G.ExpMega = (() => {
  const D = G.EXP_MEGA_DATA || [];
  // ---------------- balance (tune here; README "DLC D14") ----------------
  const K = {
    LV: 40,                 // the first level-up a Mega is offered at (ours: late in a run, the study's "late-run power spike")
    AGAIN: 5,               // "Not yet": offered again this many levels later
    H_K: 1.12,              // a battle-sprite Mega stands this much taller than the member's own sheet
    SRC: '/overworld/data/pokemon/',   // the overworld battle system's sprites (deployed with the site: magepunk-owdata)
    IFRAMES: 1.2            // a moment of i-frames as it Mega Evolves (the flash)
  };
  const T = G.I18n;
  const F = (es, ...v) => { const en = T.lang === 'en' && G.ExpEN[es]; let i = 0; return en ? en.replace(/\{x\}/g, () => v[i++]) : T.f(es, ...v); };
  const LG = () => G.ExpLeague;
  const BY = {}, OF = {};
  for (const e of D) { BY[e.id] = e; (OF[e.sp] = OF[e.sp] || []).push(e); }
  const baseName = sp => (G.DEX_BY[sp] ? T.t(G.DEX_BY[sp].name) : '#' + sp);
  /** "Mega Charizard X" (es "Mega-Charizard X"). */
  const nameOf = e => F('Mega-{x}', baseName(e.sp) + (e.suf ? ' ' + e.suf : ''));
  /** The Megas species sp can become. */
  const of = sp => OF[sp] || [];
  /** The Megas of League member m's line (any stage). */
  const lineOf = m => (LG() ? LG().stagesOf(m) : [m.dex]).reduce((a, d) => a.concat(of(d)), []);
  /** The League card's line: "Charizard → Mega Charizard X / Mega Charizard Y (from Lv 40)" ('' when the line has none). */
  function textOf(m) {
    const l = lineOf(m);
    if (!l.length) return '';
    const by = {};
    for (const e of l) (by[e.sp] = by[e.sp] || []).push(nameOf(e));
    return Object.keys(by).map(sp => baseName(+sp) + ' → ' + by[sp].join(' / ')).join(' · ') + ' (' + F('desde Nv. {x}', K.LV) + ')';
  }
  /** Its battle sprite's URL, or null (composed). */
  const srcOf = e => (e && e.spr ? K.SRC + e.spr : null);

  // ---------------- the look ----------------
  const imgs = {};
  /** The Mega's battle sprite once loaded (it starts loading on the first call), else null. */
  function img(e) {
    if (!e || !e.spr || typeof Image === 'undefined') return null;
    let s = imgs[e.id];
    if (!s) {
      s = imgs[e.id] = { im: new Image(), ok: false, failed: false };
      s.im.crossOrigin = 'anonymous';   // (301 to magepunk-owdata.pages.dev: CORS, so the hurt flash's canvas stays clean)
      s.im.onload = () => { s.ok = true; };
      s.im.onerror = () => { s.failed = true; };
      s.im.src = K.SRC + e.spr;
    }
    return s.ok ? s.im : null;
  }
  const preload = e => { img(e); };
  const TAU = Math.PI * 2;
  /** The Mega aura at the feet (under the sprite). */
  function aura(ctx, x, y, r, t) {
    ctx.save();
    const a = 0.32 + 0.12 * Math.sin(t * 5);
    const g = ctx.createRadialGradient(x, y, r * 0.2, x, y, r * 1.6);
    g.addColorStop(0, 'rgba(255,240,255,' + a + ')');
    g.addColorStop(0.55, 'rgba(214,92,255,' + a * 0.8 + ')');
    g.addColorStop(1, 'rgba(255,140,60,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.ellipse(x, y, r * 1.6, r * 0.7, 0, 0, TAU); ctx.fill();
    ctx.restore();
  }
  /** The keystone's sign over the head: a ring in the Mega symbol's three colours round a white core. */
  function emblem(ctx, x, y, t) {
    ctx.save();
    const s = 7 + Math.sin(t * 4) * 0.6;
    const cols = ['#ff9a2e', '#e050e8', '#3fa2ff'];
    ctx.lineWidth = 3;
    for (let i = 0; i < 3; i++) {
      ctx.strokeStyle = cols[i];
      ctx.beginPath(); ctx.arc(x, y, s, t * 1.5 + i * TAU / 3, t * 1.5 + i * TAU / 3 + TAU / 3 - 0.35); ctx.stroke();
    }
    ctx.fillStyle = '#ffffff'; ctx.beginPath(); ctx.arc(x, y, s * 0.42, 0, TAU); ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,.55)'; ctx.lineWidth = 1; ctx.beginPath(); ctx.arc(x, y, s + 1.6, 0, TAU); ctx.stroke();
    ctx.restore();
  }
  const RIGHT = [false, true, true, true, false, false, false, false];   // (rows 1-3 face right: the battle front is mirrored)
  /** A Mega's animator: the member's own (so every base call works: loop, play, busy, the frames, the size), drawn as the Mega. */
  class Anim extends G.Sprites.Animator {
    constructor(dex, scale, shiny, e) { super(dex, scale, shiny); this.mega = e; preload(e); }
    /** The member's own height on the field (world units), the size the Mega's picture is drawn to. */
    height() {
      const m = G.Sprites.animMeta(this.dex, 'Idle');
      return (m ? m.ay : 24) * G.Sprites.PX * this.scale * G.Sprites.artScale(this.dex);
    }
    draw(ctx, x, y, opts = {}) {
      const e = this.mega, t = this.clock || 0, alpha = opts.alpha == null ? 1 : opts.alpha;
      if (alpha <= 0) return;
      const h0 = this.height(), r = Math.max(10, G.Sprites.bodyRadius(this.dex, this.scale));
      if (alpha >= 0.5) aura(ctx, x, y, r, t);
      const im = img(e);
      let top = y - h0;
      if (im) {
        // the battle front at a whole-pixel scale near the member's height (crisp pixel art), feet on (x, y)
        const want = h0 * K.H_K, k = Math.max(1, Math.round(want / im.height)), w = im.width * k, h = im.height * k;
        const bob = this.cur === 'Walk' && !this.once ? Math.round(Math.abs(Math.sin(t * 9)) * 2 * G.Sprites.PX * this.scale) : 0;
        const flip = RIGHT[this.dir || 0];
        const prev = ctx.globalAlpha, sm = ctx.imageSmoothingEnabled;
        ctx.save();
        ctx.imageSmoothingEnabled = false;
        ctx.translate(Math.round(x), 0);
        if (flip) ctx.scale(-1, 1);
        const dx = Math.round(-w / 2), dy = Math.round(y - h) - bob;
        if (alpha < 1) ctx.globalAlpha = prev * alpha;
        if (!opts.flash || opts.softFlash) ctx.drawImage(im, dx, dy, w, h);
        if (opts.flash) { if (opts.softFlash) ctx.globalAlpha = prev * alpha * 0.55; ctx.drawImage(G.Sprites.white(im), dx, dy, w, h); }
        ctx.restore();
        ctx.imageSmoothingEnabled = sm;
        top = y - h - bob;
      } else super.draw(ctx, x, y, opts);   // (composed: the member's own sheet; the aura and the sign make it the Mega)
      if (alpha >= 0.5) emblem(ctx, x, top - 9, t);
    }
  }
  /** Player / puppet p takes Mega e's look (its dex, size and passive stay the member's). */
  function look(p, e) {
    if (!p || !e) return false;
    const dir = p.anim ? p.anim.dir : 0, cur = p.anim ? p.anim.base : 'Idle';
    p.anim = new Anim(p.dex, p.anim ? p.anim.scale : 1, !!p.shiny, e);
    p.anim.dir = dir;
    p.anim.loop(cur || 'Idle');
    p.xmegaLook = e.id;
    return true;
  }
  /** The level-up card's picture of Mega e: {img: its battle sprite} or {sprite: the member's form} (composed). */
  const cardArt = (e, form) => (e.spr ? { img: srcOf(e) } : { sprite: form });

  let styled = false;
  function style() {
    if (styled || typeof document === 'undefined') return;
    styled = true;
    const st = document.createElement('style'); st.id = 'exp-d14-mega';
    st.textContent = '#cards .ico-item[src*="/overworld/data/pokemon/"] { object-fit: contain; width: 48px; height: 40px; image-rendering: pixelated; }';
    document.head.appendChild(st);
  }
  style();

  return { K, D, BY, OF, of, lineOf, nameOf, textOf, srcOf, img, preload, look, cardArt, Anim, aura, emblem };
})();
